namespace {
int checks=0,failures=0;void expect(bool yes,const std::string& text){++checks;if(!yes){++failures;std::cerr<<"FAIL: "<<text<<'\n';}}
template<class F>void rejects(F fn,int code,const char* text){bool okay=false;try{fn();}catch(const penta::mechanics::Error& e){okay=e.status==code;}expect(okay,text);}
int potential(void* raw,const double* q,uint32_t order,double* value,double* first,double* second,char*,uint64_t){const double gravity=raw?*static_cast<double*>(raw):0;value[0]=gravity*q[1];if(order>=1){first[0]=0;first[1]=gravity;}if(order>=2)std::fill_n(second,4,0);return 0;}
int circle(void*,const double* q,uint32_t order,double* value,double* first,double* second,char*,uint64_t){value[0]=q[0]*q[0]+q[1]*q[1]-1;if(order>=1){first[0]=2*q[0];first[1]=2*q[1];}if(order>=2){second[0]=second[3]=2;second[1]=second[2]=0;}return 0;}
int line(void* raw,const double* q,uint32_t order,double* value,double* first,double* second,char*,uint64_t){value[0]=q[0]+q[1]-(raw?*static_cast<double*>(raw):0);if(order>=1)first[0]=first[1]=1;if(order>=2)std::fill_n(second,4,0);return 0;}
int duplicate(void*,const double* q,uint32_t order,double* value,double* first,double* second,char*,uint64_t){value[0]=q[0]*q[0]+q[1]*q[1]-1;value[1]=2*value[0];if(order>=1){first[0]=2*q[0];first[1]=2*q[1];first[2]=4*q[0];first[3]=4*q[1];}if(order>=2){std::fill_n(second,8,0);second[0]=second[3]=2;second[4]=second[7]=4;}return 0;}
int scaledCircle(void* raw,const double* q,uint32_t order,double* value,double* first,double* second,char* error,uint64_t capacity){circle(nullptr,q,order,value,first,second,error,capacity);const auto scale=*static_cast<double*>(raw);value[0]*=scale;if(order>=1)for(unsigned n=0;n<2;++n)first[n]*=scale;if(order>=2)for(unsigned n=0;n<4;++n)second[n]*=scale;return 0;}
struct Cancellation{std::atomic_bool flag{false};unsigned calls=0;};
int cancellingCircle(void* raw,const double* q,uint32_t order,double* value,double* first,double* second,char* error,uint64_t capacity){auto& context=*static_cast<Cancellation*>(raw);if(++context.calls==20)context.flag=true;return circle(nullptr,q,order,value,first,second,error,capacity);}
std::array<double,2> reference(double angle,double speed,double gravity,double time){const double h=1e-5;const auto steps=static_cast<unsigned>(std::round(time/h));for(unsigned step=0;step<steps;++step){const double a1=speed,b1=-gravity*std::sin(angle),a2=speed+h*b1/2,b2=-gravity*std::sin(angle+h*a1/2),a3=speed+h*b2/2,b3=-gravity*std::sin(angle+h*a2/2),a4=speed+h*b3,b4=-gravity*std::sin(angle+h*a3);angle+=h*(a1+2*a2+2*a3+a4)/6;speed+=h*(b1+2*b2+2*b3+b4)/6;}return {std::sin(angle),-std::cos(angle)};}
penta_holonomic_request_v1 request(const std::vector<double>& q,const std::vector<double>& v,const std::vector<double>& mass){penta_holonomic_request_v1 r{};r.dimension=2;r.constraints=1;r.q0=q.data();r.v0=v.data();r.mass=mass.data();r.t1=1;r.time_step=.01;r.sample_step=.01;r.tolerance=1e-13;r.regularity_tolerance=1e-12;r.max_wall_seconds=30;r.max_iterations=30;r.max_steps=100000;r.max_evaluations=1000000;r.max_work=1000000000;r.potential=potential;r.constraint=circle;return r;}
void native(){
    penta::mechanics::ConstrainedModule module;std::vector<double> q{1,0},v{0,1},mass{1,0,0,1};auto r=request(q,v,mass);auto coarseRequest=r;coarseRequest.time_step=coarseRequest.sample_step=.1;const auto coarse=module.solve(coarseRequest);auto fineRequest=coarseRequest;fineRequest.time_step=fineRequest.sample_step=.05;const auto fine=module.solve(fineRequest);const auto exact=std::array{std::cos(1.0),std::sin(1.0)};const auto error=[&](const auto& output){const auto n=output.q.size();return std::hypot(output.q[n-2]-exact[0],output.q[n-1]-exact[1]);};expect(error(fine)<error(coarse)*.27,"RATTLE has second-order convergence against exact unit-circle motion.");expect(fine.report.max_position_error<1e-12&&fine.report.max_velocity_error<1e-12,"RATTLE retains both holonomic position and tangent velocity constraints.");expect(fine.report.max_relative_energy_drift<1e-11,"Free constrained rotation preserves kinetic energy to solver precision.");expect(std::all_of(fine.lambda.begin(),fine.lambda.end(),[](double x){return std::abs(x-.5)<1e-11;}),"Generated-Hessian multiplier formula agrees with centripetal constraint force.");
    auto shakeRequest=fineRequest;shakeRequest.method=PENTA_HOLONOMIC_SHAKE;const auto shake=module.solve(shakeRequest);double positionDifference=0;for(std::size_t at=0;at<shake.q.size();++at)positionDifference=std::max(positionDifference,std::abs(shake.q[at]-fine.q[at]));expect(positionDifference<1e-11&&shake.report.max_position_error<1e-12,"SHAKE reproduces position-Verlet constrained positions.");expect(shake.report.max_velocity_error>1e-4,"SHAKE explicitly exposes its unprojected endpoint velocity residual.");
    double gravity=9.81;const double angle=.6,speed=.1;q={std::sin(angle),-std::cos(angle)};v={speed*std::cos(angle),speed*std::sin(angle)};r=request(q,v,mass);r.t1=2;r.potential_context=&gravity;r.time_step=r.sample_step=.02;const auto pendulumCoarse=module.solve(r);r.time_step=r.sample_step=.01;const auto pendulumFine=module.solve(r);const auto exactPendulum=reference(angle,speed,gravity,2);const auto pError=[&](const auto& output){return std::hypot(output.q[output.q.size()-2]-exactPendulum[0],output.q.back()-exactPendulum[1]);};expect(pError(pendulumFine)<pError(pendulumCoarse)*.3,"Gravitational constrained pendulum converges against an independent angle-coordinate RK4 reference.");expect(pendulumFine.report.max_position_error<1e-12&&pendulumFine.report.max_velocity_error<1e-12&&pendulumFine.report.max_relative_energy_drift<.001,"Pendulum constraint and numerical energy diagnostics remain bounded.");std::cout<<"Pendulum independent position errors "<<pError(pendulumCoarse)<<" -> "<<pError(pendulumFine)<<'\n';
    q={1.01,0};v={.1,1};r=request(q,v,mass);rejects([&]{module.solve(r);},1,"Inconsistent initial data are rejected by default.");r.project_initial=1;const auto projected=module.solve(r);expect(std::abs(projected.q[0]-1)<1e-12&&std::abs(projected.v[0])<1e-12,"Explicit mass-normal position/tangent projection creates consistent initials.");expect(std::abs(projected.report.initial_q_correction[0]+.01)<1e-12&&std::abs(projected.report.initial_v_correction[0]+.1)<1e-12,"Initial projection corrections are explicitly reported.");
    q={0,0};v={1,-1};mass={2,1,1,2};r=request(q,v,mass);r.constraint=line;const auto fullMass=module.solve(r);expect(std::abs(fullMass.q[fullMass.q.size()-2]-1)<1e-12&&std::abs(fullMass.q.back()+1)<1e-12,"Constant full SPD mass supports a real linear holonomic constraint.");expect(std::abs(fullMass.p[0]-1)<1e-12&&std::abs(fullMass.p[1]+1)<1e-12,"Physical momentum uses the full mass matrix.");
    double offset=1;q={0,0};v={1,0};mass={2,0,0,1};r=request(q,v,mass);r.constraint=line;r.constraint_context=&offset;r.project_initial=1;r.t1=0;const auto weightedProjection=module.solve(r);expect(std::abs(weightedProjection.q[0]-1.0/3)<1e-12&&std::abs(weightedProjection.q[1]-2.0/3)<1e-12&&std::abs(weightedProjection.v[0]-2.0/3)<1e-12&&std::abs(weightedProjection.v[1]+2.0/3)<1e-12,"Mass-normal initial projection agrees with an independent weighted linear projection.");
    mass={1,0,0,1};q={1,0};v={0,1};r=request(q,v,mass);auto invalid=r;invalid.constraints=2;invalid.constraint=duplicate;rejects([&]{module.solve(invalid);},2,"Dependent holonomic constraints are rejected.");invalid=r;invalid.sample_step=.015;rejects([&]{module.solve(invalid);},1,"Off-grid sample interpolation is rejected.");invalid=r;invalid.max_work=1;rejects([&]{module.solve(invalid);},7,"Holonomic native work budget is enforced.");invalid=r;invalid.max_evaluations=1;rejects([&]{module.solve(invalid);},7,"Holonomic callback evaluation budget is enforced.");auto cancelled=std::make_shared<std::atomic_bool>(true);rejects([&]{module.solve(r,cancelled);},3,"Cancellation releases a reserved native mechanics call.");mass={1,2,2,1};r.mass=mass.data();rejects([&]{module.solve(r);},1,"Indefinite mass operators are rejected.");mass={1,0,0,1};r.mass=mass.data();const auto recovered=module.solve(r);expect(recovered.report.steps==100,"Valid solve succeeds after budget/cancellation/regularity failures.");
    auto first=std::async(std::launch::async,[&]{return module.solve(r);});auto second=std::async(std::launch::async,[&]{return module.solve(r);});const auto a=first.get(),b=second.get();expect(a.q==b.q&&a.v==b.v,"Independent concurrent callers respect the shared CPU reservation and produce identical histories.");
    double equationScale=1e300;mass={1e308,0,0,1e308};q={1,0};v={0,1.4};r=request(q,v,mass);r.constraint=scaledCircle;r.constraint_context=&equationScale;r.t1=0;const auto extreme=module.solve(r);expect(std::abs(extreme.energy[0]/9.8e307-1)<1e-14&&std::abs(extreme.lambda[0]/9.8e7-1)<1e-14,"Extended energy and multiplier contractions preserve representable extreme-scale results.");
    mass={1,0,0,1};q={1,0};v={0,1};r=request(q,v,mass);Cancellation cancellation;r.constraint=cancellingCircle;r.constraint_context=&cancellation;const auto flag=std::shared_ptr<std::atomic_bool>(&cancellation.flag,[](std::atomic_bool*){});rejects([&]{module.solve(r,flag);},3,"Cancellation during native iterations releases the shared reservation.");
}
#ifndef PENTA_HOLONOMIC_NATIVE_ONLY
void language(){
    penta::runtime::ExecutionOptions options;options.dataDirectory=std::filesystem::temp_directory_path()/("penta-holonomic-language-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(options.dataDirectory);auto run=[&](const std::string& source,bool good=true){const auto result=penta::runtime::execute(source,{},options);expect(result.ok()==good,source);if(good&&!result.ok()){for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';}return result;};
    const std::string rotation="native function real zero_potential(real x,real y){return 0;}native function real circle_constraint(real x,real y,real radius){return x*x+y*y-radius*radius;}record motion=constrainedmechanics(@zero_potential,@circle_constraint,[1,0],[0,1],options(constraint_parameters=options(radius=1),t1=1,time_step=0.01,sample_step=0.1));assert(motion.max_position_error<1e-10);assert(motion.max_velocity_error<1e-10);assert(motion.max_relative_energy_drift<1e-10);assert(norm(motion.lambda-0.5*ones(11,1))<1e-9);";run(rotation);const auto cached=run(rotation);if(cached.ok())expect(cached.nativeCompilation.compilerAttempts==0,"Unchanged constrained potential/constraint bodies reuse native shared libraries.");
    run("native function real gravity_potential(real x,real y,real gravity){return gravity*y;}native function real circle_constraint(real x,real y){return x*x+y*y-1;}record motion=constrainedmechanics(@gravity_potential,@circle_constraint,[0,-1],[1,0],options(parameters=options(gravity=9.81),t1=0.1,time_step=0.01,sample_step=0.01));assert(motion.constraint_derivatives==\"compiler_generated_analytic_gradient_hessian\");assert(motion.lambda(1)>5);assert(motion.max_position_error<1e-10);");
    run("native function real flat_potential(real a,real b,real c,real d,real e){return 0;}native function [real gc,real gz,real gw,real ge] five_constraints(real a,real b,real c,real d,real e){return a*a+b*b-1,c,d,e;}pentarnion q0=1;pentarnion v0=i;record motion=constrainedmechanics(@flat_potential,@five_constraints,q0,v0,options(t1=0.1,time_step=0.01,sample_step=0.01));assert(motion.coordinate_dimension==5);assert(motion.constraint_count==4);assert(motion.flattened_pentarnion_input==1);assert(motion.max_velocity_error<1e-10);");
    run("native function real V(real x,real y){return 0;}native function real g(real x,real y){return x*x+y*y-1;}record motion=constrainedmechanics(@V,@g,[1.01,0],[0.1,1],options(initial_policy=\"project\",t1=0.1));assert(abs(motion.initial_q_correction(1)+0.01)<1e-9);assert(abs(motion.initial_v_correction(1)+0.1)<1e-9);");
    run("native function real V(real x,real y){return 0;}native function real g(real x,real y){return x*x+y*y-1;}record motion=constrainedmechanics(@V,@g,[1.1,0],[0,1]);",false);
    run("native function real harmonic_force(real t,real q){return -q;}record existing=mechanics(@harmonic_force,1,0,options(form=\"newton\",method=\"verlet\",t1=0.1,time_step=0.01,sample_step=0.01));assert(abs(existing.q(end)-cos(0.1))<1e-5);");
    penta::language::AnalysisOptions old;old.languageVersion="0.1";expect(!penta::language::analyse(rotation,old).ok(),"Holonomic extension does not change language0.1.");
}
#endif
}
int main(){try{native();
#ifndef PENTA_HOLONOMIC_NATIVE_ONLY
language();
#endif
}catch(const std::exception& e){++failures;std::cerr<<e.what()<<'\n';}std::cout<<checks<<" holonomic mechanics checks, "<<failures<<" failures\n";return failures?1:0;}
